862: /* ------------------------------ main update ------------------------------ */
863: function update(dtRaw) {
864:   if (paused) return;
865:   gameT += dtRaw;
866:   timeScale = lerp(timeScale, timeScaleTarget, Math.min(1, dtRaw * 8));
867:   if (slowmoT > 0) {
868:     slowmoT -= dtRaw;
869:     if (slowmoT <= 0) timeScaleTarget = 1;
870:   }
871:   if (hitstop > 0) hitstop -= dtRaw;
872:   const sdt = hitstop > 0 ? 0 : dtRaw * timeScale;
873: 
874:   shake = Math.max(0, shake - dtRaw * 46);
875:   const sh = shake;
876:   shakeX = sh > 0.1 ? rand(-sh, sh) : 0;
877:   shakeY = sh > 0.1 ? rand(-sh, sh) : 0;
878: 
879:   // moving platforms
880:   for (const pl of platforms) {
881:     if (!pl.vx) pl.vx = (Math.random() < 0.5 ? -1 : 1) * 60 * S;
882:     pl.x += pl.vx * (hitstop > 0 ? 0 : dtRaw * timeScale);
883:     if (pl.x < arena.left) { pl.x = arena.left; pl.vx = Math.abs(pl.vx); }
884:     if (pl.x + pl.w > arena.right) { pl.x = arena.right - pl.w; pl.vx = -Math.abs(pl.vx); }
885:   }
886:    // keep platforms on the same row from phasing through each other
887:    for (let i = 0; i < platforms.length; i++) {
888:      for (let j = i + 1; j < platforms.length; j++) {
889:        const a = platforms[i], b = platforms[j];
890:        if (Math.abs(a.y - b.y) > 6 * S) continue;
891:        const overlap = Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x);
892:        if (overlap > 0) {
893:          const push = overlap / 2 + 0.5 * S;
894:          a.x -= push; b.x += push;
895:          const va = a.vx; a.vx = b.vx; b.vx = va;
896:          a.x = clamp(a.x, arena.left, arena.right - a.w);
897:          b.x = clamp(b.x, arena.left, arena.right - b.w);
898:        }
899:      }
900:    }
901: 
902:   if (state === 'title') {
903:     for (const p of players) updatePlayer(p, sdt);
904:     updateBalls(sdt);
905:     updateParticles(sdt);
906:     updateFloaters(sdt);
907:     return;
908:   }
909:   if (!match) return;
910: 
911:   if (state === 'countdown') {
912:     countdown -= dtRaw;
913:     const n = Math.max(1, Math.ceil(countdown));
914:     if (String(n) !== countdownLabel && countdown > 0) {
915:       countdownLabel = String(n);
916:       el.rcCount.textContent = countdownLabel;
917:       el.rcCount.style.animation = 'none';
918:       void el.rcCount.offsetWidth;
919:       el.rcCount.style.animation = '';
920:       sfx.count();
921:     }
922:     for (const p of players) updatePlayer(p, sdt);
923:     updateParticles(sdt);
924:     updateFloaters(sdt);
925:     if (countdown <= 0) beginPlay();
926:     updateHud();
927:     return;
928:   }
929: 
930:   if (state === 'play') {
931:     roundTime -= sdt;
932:     if (roundTime <= 0) {
933:       roundTime = 0;
934:       const [a, b] = players;
935:       const winner = a.hp > b.hp ? 0 : b.hp > a.hp ? 1 : null;
936:       finishRound(winner, 'time');
937:     }
938: 
939:     if (roundMod.storm) {
940:       stormTimer -= sdt;
941:       if (stormTimer <= 0) { stormTimer = rand(3.2, 5); spawnStormBall(); }
942:     }
943:     heartTimer -= sdt;
944:     if (heartTimer <= 0) {
945:       heartTimer = rand(2.5, 4);
946:       const hearts = pickups.filter(p => p.type === 'heart').length;
947:       if (players.some(p => p.hp < p.maxHp * 0.7) && hearts < 1) spawnPickup('heart');
948:     }
949:     chickenTimer -= sdt;
950:     if (chickenTimer <= 0) {
951:       chickenTimer = rand(5, 10);
952:       const chickens = pickups.filter(p => p.type === 'chicken').length;
953:       if (chickens < 1) spawnPickup('chicken');
954:     }
955:     shieldTimer -= sdt;
956:     if (shieldTimer <= 0) {
957:       shieldTimer = rand(5, 10);
958:       const shields = pickups.filter(p => p.type === 'shield').length;
959:       if (shields < 1) spawnPickup('shield');
960:     }
961:   }
962: 
963:   for (const p of players) updatePlayer(p, sdt);
964:   updateBalls(sdt);
965:   updatePickups(sdt);
966:   updateParticles(sdt);
967:   updateFloaters(sdt);
968: 
969:   if (state === 'roundEnd') {
970:     roundEndT -= dtRaw;
971:     if (roundEndT <= 0) {
972:       if (match.scores[0] >= 3 || match.scores[1] >= 3) {
973:         endMatch(match.scores[0] >= 3 ? 0 : 1);
974:       } else {
975:         match.round++;
976:         startRound();
977:       }
978:     }
979:   }
980: 
981:   if (state === 'matchEnd') {
982:     endDelay -= dtRaw;
983:     if (endDelay <= 0 && !endShown) showEndScreen();
984:   }
985: 
986:   updateHud();
987: }
