401: /* ------------------------------ fx updates ------------------------------ */
402: function updateParticles(dt) {
403:   for (const p of particles) {
404:     p.life -= dt;
405:     if (p.life <= 0) continue;
406:     p.x += p.vx * dt;
407:     p.y += p.vy * dt;
408:     p.vy += p.grav * dt;
409:     p.vx *= Math.pow(p.drag, dt * 60);
410:     p.vy *= Math.pow(p.drag, dt * 60);
411:     p.rot += p.spin * dt;
412:   }
413:   particles = particles.filter(p => p.life > 0);
414: }
415: function updateFloaters(dt) {
416:   for (const f of floaters) {
417:     f.life -= dt;
418:     f.y += f.vy * dt;
419:     f.vy *= Math.pow(0.9, dt * 60);
420:   }
421:   floaters = floaters.filter(f => f.life > 0);
422: }

